on the other side of the channel.

# Examples

```
use std::thread;
use std::time::Duration;
use crossbeam_channel::{unbounded, RecvError};

let (s, r) = unbounded();

thread::spawn(move || {
    thread::sleep(Duration::from_secs(1));
    s.send(5).unwrap();
    drop(s);
});

assert_eq!(r.recv(), Ok(5));
assert_eq!(r.recv(), Err(RecvError));
